SourceCode.Declaration:
/// <summary>
/// A small JSON writer for the replies of TEST_AutomationService, which the harness script
/// Tools/XppLoop/Invoke-XppLoop.ps1 parses. Write a value with a name inside an object and
/// with an empty name inside an array:
///   json.beginObject(); json.addString('step', 'MD12.Seed.TC01');
///   json.beginArray('infolog'); json.addString('', 'line 1'); json.endArray();
///   json.endObject(); return json.toString();
/// </summary>
public final class TEST_AutomationJson
{
    System.Text.StringBuilder builder;
    boolean                   needsComma;
    str                       controlChars;
}

Method.Source:
public void new()
{
    int i;

    builder    = new System.Text.StringBuilder();
    needsComma = false;

    // Control characters other than tab, line feed and carriage return are dropped.
    controlChars = '';
    for (i = 1; i < 32; i++)
    {
        if (i != 9 && i != 10 && i != 13)
        {
            controlChars += num2Char(i);
        }
    }
}

public static TEST_AutomationJson construct()
{
    return new TEST_AutomationJson();
}

/// <summary>
/// Returns _value as a JSON string literal, with quotes, backslashes, tabs and line breaks
/// escaped.
/// </summary>
public str quote(str _value)
{
    str value = strRem(_value, controlChars);

    value = strReplace(value, '\\', '\\\\');
    value = strReplace(value, '"', '\\"');
    value = strReplace(value, num2Char(13), '\\r');
    value = strReplace(value, num2Char(10), '\\n');
    value = strReplace(value, num2Char(9), '\\t');

    return '"' + value + '"';
}

private void writeName(str _name)
{
    if (needsComma)
    {
        builder.Append(',');
    }

    if (_name)
    {
        builder.Append(this.quote(_name));
        builder.Append(':');
    }

    needsComma = true;
}

public void beginObject(str _name = '')
{
    this.writeName(_name);
    builder.Append('{');
    needsComma = false;
}

public void endObject()
{
    builder.Append('}');
    needsComma = true;
}

public void beginArray(str _name = '')
{
    this.writeName(_name);
    builder.Append('[');
    needsComma = false;
}

public void endArray()
{
    builder.Append(']');
    needsComma = true;
}

public void addString(str _name, str _value)
{
    this.writeName(_name);
    builder.Append(this.quote(_value));
}

public void addInt(str _name, int64 _value)
{
    this.writeName(_name);
    builder.Append(int642Str(_value));
}

public void addBool(str _name, boolean _value)
{
    this.writeName(_name);
    builder.Append(_value ? 'true' : 'false');
}

/// <summary>
/// Writes a UTC date and time as an ISO 8601 string ending in Z, or null when it is empty.
/// </summary>
public void addDateTime(str _name, utcdatetime _value)
{
    this.writeName(_name);

    if (_value == DateTimeUtil::minValue())
    {
        builder.Append('null');
    }
    else
    {
        builder.Append(this.quote(DateTimeUtil::toStr(_value) + 'Z'));
    }
}

/// <summary>
/// Writes infolog data as an array of { "type": "info|warning|error", "message": "..." }.
/// At most _maxLines lines are written; returns the number of lines left out.
/// </summary>
public int addInfolog(str _name, container _infologData, int _maxLines = 200)
{
    SysInfologEnumerator    enumerator;
    SysInfologMessageStruct messageStruct;
    int                     lines   = 0;
    int                     skipped = 0;

    this.beginArray(_name);

    if (conLen(_infologData))
    {
        enumerator = SysInfologEnumerator::newData(_infologData);

        while (enumerator.moveNext())
        {
            if (lines >= _maxLines)
            {
                skipped++;
                continue;
            }

            messageStruct = new SysInfologMessageStruct(enumerator.currentMessage());

            this.beginObject();
            this.addString('type', TEST_AutomationJson::exceptionName(enumerator.currentException()));
            this.addString('message', messageStruct.message());
            this.endObject();
            lines++;
        }
    }

    this.endArray();

    return skipped;
}

public static str exceptionName(Exception _exception)
{
    switch (_exception)
    {
        case Exception::Info:
            return 'info';
        case Exception::Warning:
            return 'warning';
        case Exception::Error:
            return 'error';
        default:
            return 'other';
    }
}
